  Future<BigInt> enqueue({required String id}) =>
      RustLib.instance.api.crateApiEngineEnqueue(that: this, id: id);

  /// Fetches lyrics for a track.
  ///
  /// # Errors
  ///
  /// Fails with a mapped [`BridgeError`].
  Future<LyricsDto> lyrics({required String id}) =>
      RustLib.instance.api.crateApiEngineLyrics(that: this, id: id);

