  Future<String> quality() =>
      RustLib.instance.api.crateApiEngineQuality(that: this);

  /// The number of queued tracks.
  Future<BigInt> queueLen() =>
      RustLib.instance.api.crateApiEngineQueueLen(that: this);

  /// Resumes playback.
  ///
  /// # Errors
  ///
  /// Fails with the `capability` kind when no audio device is available.
  Future<void> resume() =>
      RustLib.instance.api.crateApiEngineResume(that: this);

  /// Searches the catalog.
  ///
  /// # Errors
  ///
  /// Fails with a mapped [`BridgeError`].
  Future<SearchResultsDto> search({required String query}) =>
      RustLib.instance.api.crateApiEngineSearch(that: this, query: query);

  /// The current session.
  Future<SessionDto> session() =>
      RustLib.instance.api.crateApiEngineSession(that: this);

  /// Sets the quality tier.
  ///
  /// Returns the tier's label so the UI can confirm what it selected.
  Future<String> setQuality({required String quality}) => RustLib.instance.api
      .crateApiEngineSetQuality(that: this, quality: quality);

